// ===== L5686-L5694 markNotificationRead =====
let notificationSocket = null;
let notificationHeartbeatTimer = null;

function getNotificationSocketUrl() {
  return `${window.location.protocol}//${window.location.hostname}:8089/notifications`;
}

function updateNotificationSocketStatus(status, message) {
  state.notificationSocketStatus = status;
  state.notificationSocketMessage = message || "";
  updateNotificationPanelDom();
}

function updateNotificationPanelDom() {
  const badge = document.getElementById("notificationBadge");
  const toggle = document.getElementById("notificationToggleBtn");
  const status = document.getElementById("notificationSocketStatus");
  const list = document.getElementById("notificationList");
  if (badge) {
    badge.textContent = String(state.unreadNotificationCount);
    badge.style.display = state.unreadNotificationCount > 0 ? "" : "none";
  }
  if (toggle) {
    toggle.classList.toggle("has-unread", state.unreadNotificationCount > 0);
  }
  if (status) {
    status.textContent = state.notificationSocketMessage || "消息通道已连接";
    status.dataset.status = state.notificationSocketStatus;
  }
  if (list) {
    list.innerHTML = renderNotificationListItems();
    bindNotificationItemEvents();
  }
}

function renderNotificationListItems() {
  return state.notifications.length
    ? state.notifications.map((item) => `
        <button class="notification-item ${item.unread ? "unread" : ""} js-notification-item" data-id="${item.id}" type="button">
          <strong>${item.title || "系统消息"}</strong>
          <p>${item.message || ""}</p>
          <span>${item.createdAt ? formatDate(item.createdAt) : ""}</span>
        </button>
      `).join("")
    : `<div class="notification-item"><strong>暂无消息</strong><p>当前还没有新的提醒。</p></div>`;
}

function bindNotificationItemEvents() {
  document.querySelectorAll(".js-notification-item").forEach((el) => {
    if (el.dataset.bound === "1") return;
    el.dataset.bound = "1";
    el.addEventListener("click", () => markNotificationRead(el.dataset.id));
  });
}

function mergeIncomingNotification(item) {
  if (!item || !item.id) return;
  const normalized = {
    ...item,
    message: item.message || item.content || "",
    unread: item.unread !== false
  };
  const index = state.notifications.findIndex((current) => current.id === normalized.id);
  if (index >= 0) {
    state.notifications.splice(index, 1, { ...state.notifications[index], ...normalized });
  } else {
    state.notifications.unshift(normalized);
  }
}

function startNotificationHeartbeat() {
  stopNotificationHeartbeat();
  notificationHeartbeatTimer = window.setInterval(() => {
    if (notificationSocket?.connected) {
      notificationSocket.emit("notification:ping");
    }
  }, 25000);
}

function stopNotificationHeartbeat() {
  if (notificationHeartbeatTimer) {
    window.clearInterval(notificationHeartbeatTimer);
    notificationHeartbeatTimer = null;
  }
}

function connectNotificationSocket() {
  if (!state.token || !state.user || typeof io !== "function") return;
  if (notificationSocket) {
    notificationSocket.auth = { token: state.token };
    notificationSocket.io.opts.auth = { token: state.token };
    if (!notificationSocket.connected) notificationSocket.connect();
    return;
  }

  notificationSocket = io(getNotificationSocketUrl(), {
    auth: { token: state.token },
    path: "/api/socket.io",
    transports: ["websocket", "polling"],
    reconnection: true,
    reconnectionAttempts: Infinity,
    reconnectionDelay: 1000,
    reconnectionDelayMax: 10000,
    timeout: 10000
  });

  notificationSocket.on("connect", () => {
    notificationSocket.emit("notification:subscribe");
    updateNotificationSocketStatus("connected", "消息通道已连接");
    startNotificationHeartbeat();
  });

  notificationSocket.io.on("reconnect_attempt", (attempt) => {
    updateNotificationSocketStatus("reconnecting", `消息通道重连中（第 ${attempt} 次）`);
  });

  notificationSocket.io.on("reconnect", () => {
    notificationSocket.emit("notification:subscribe");
    updateNotificationSocketStatus("connected", "消息通道已恢复");
  });

  notificationSocket.on("disconnect", (reason) => {
    stopNotificationHeartbeat();
    updateNotificationSocketStatus("disconnected", `消息通道已断开，正在自动重连：${reason}`);
  });

  notificationSocket.on("connect_error", () => {
    updateNotificationSocketStatus("reconnecting", "消息通道连接失败，正在自动重连");
  });

  notificationSocket.on("notification:new", (item) => {
    mergeIncomingNotification(item);
    state.unreadNotificationCount = Number(item?.unreadCount ?? state.unreadNotificationCount + 1);
    updateNotificationPanelDom();
  });

  notificationSocket.on("notification:unread", (payload) => {
    state.unreadNotificationCount = Number(payload?.unreadCount || 0);
    updateNotificationPanelDom();
  });

  notificationSocket.on("notification:error", (payload) => {
    updateNotificationSocketStatus("error", payload?.message || "消息通道异常");
  });
}

function disconnectNotificationSocket() {
  stopNotificationHeartbeat();
  if (notificationSocket) {
    notificationSocket.disconnect();
    notificationSocket = null;
  }
  updateNotificationSocketStatus("idle", "");
}

async function markNotificationRead(id) {
  if (!id) return;
  await api(`/api/notifications/${id}/read`, {
    method: "POST"
  });
  const item = state.notifications.find((current) => current.id === id);
  if (item?.unread) {
    state.unreadNotificationCount = Math.max(0, state.unreadNotificationCount - 1);
  }
  if (item) {
    item.unread = false;
    item.readStatus = 1;
  }
  updateNotificationPanelDom();
}
